const LEGACY_REPORT_LESSONS={"freud_a001":{"id":"freud_a001","title":"Relatório dos meus Estudos em Paris e Berlim #1","minutes":18,"hook":"Qual é o problema teórico por trás de “charcot, a salpêtrière e o problema da histeria” — e por que não basta decorar sua definição?","lead":"Nesta aula de leitura, o foco é “charcot, a salpêtrière e o problema da histeria”. Vamos situar o problema no pensamento freudiano, explicitar o raciocínio e observar os limites de sua utilização clínica. O conteúdo abaixo é uma elaboração didática original a partir do tema do texto — não é uma transcrição de aulas de terceiros.","blocks":[{"title":"Antes de interpretar: situação histórica","body":"No relatório de sua viagem de estudos, Freud registra o impacto de Jean-Martin Charcot e da clínica neurológica francesa. A histeria era disputada entre modelos anatômicos, hipóteses funcionais e descrições clínicas; os sintomas nem sempre se ajustavam a lesões detectáveis. O texto pertence à fase pré-psicanalítica: é histórico, não um manifesto do inconsciente freudiano já constituído."},{"title":"Entenda o conceito: Charcot, a Salpêtrière e o problema da histeria","body":"A observação clínica colocava Freud diante de sintomas motores e sensoriais cuja distribuição não coincidia necessariamente com trajetos anatômicos conhecidos. Isso não autoriza concluir que fossem inventados. Para ler o relatório, identifique o que a neurologia da época conseguia explicar e onde surgiam perguntas novas.\n\nRepare que esse recorte não esgota a obra. O exercício aqui é distinguir o que Freud descreve, a interpretação que propõe e o que permanece em aberto. Quando uma hipótese for construída sobre observações clínicas, não a trate automaticamente como regra para toda pessoa ou período histórico."},{"title":"Articulações, controvérsias e limites","body":"A história da psicanálise não começa com um sistema pronto; nasce de controvérsias médicas e clínicas. Diferencie sempre uma observação histórica de uma explicação validada hoje.\n\nO texto foi redigido em 1886 e incluído no primeiro módulo por fidelidade à sequência do sumário."},{"title":"Roteiro de estudo ativo","body":"1. Abra o texto de Freud indicado nas referências e localize os argumentos relacionados a “charcot, a salpêtrière e o problema da histeria”.\n\n2. Escreva com suas palavras a pergunta que motivou o argumento e a resposta provisória oferecida por Freud.\n\n3. Marque uma hipótese e uma observação: elas têm o mesmo estatuto?\n\n4. Compare sua resposta com a seção anterior e registre na área de anotações uma dúvida para retomar mais tarde."}],"example":{"title":"Situação para pensar, sem diagnosticar","body":"Considere alguém com uma paralisia funcional. A investigação contemporânea exige avaliação adequada e não permite concluir, com base apenas em um sintoma, que exista um conflito inconsciente específico. O interesse histórico de Freud estava na insuficiência de certas explicações disponíveis.\n\nAgora retome o foco desta aula: charcot, a salpêtrière e o problema da histeria. Que novas perguntas ele permite formular sem oferecer uma resposta pronta?"},"terms":[{"term":"Histeria","desc":"Categoria histórica de sintomas e organizações clínicas, com sentidos variáveis conforme a época."},{"term":"Charcot","desc":"Neurologista francês cujas aulas influenciaram a formação de Freud."}],"quiz":{"question":"Qual cuidado é essencial ao estudar “charcot, a salpêtrière e o problema da histeria” nesta obra?","options":["Usar o conceito como diagnóstico imediato de pessoas reais, dispensando associações e contexto.","Examinar o argumento no contexto de 1886, distinguindo hipótese, exemplos e limites da interpretação.","Tomar qualquer caso citado como demonstração de uma lei psicológica universal."],"correct":1,"feedback":"O tópico “Charcot, a Salpêtrière e o problema da histeria” exige localizar a hipótese no texto, acompanhar sua construção e reconhecer o que ela não demonstra. A formulação histórica não substitui avaliação clínica atual."},"refs":["Freud (1886) — Relatório dos meus Estudos em Paris e Berlim. Verifique a tradução e a edição utilizada.","Freud, S. — Obras completas; compare a organização cronológica e notas editoriais da edição consultada."]},"freud_a002":{"id":"freud_a002","title":"Relatório dos meus Estudos em Paris e Berlim #2","minutes":15,"hook":"Qual é o problema teórico por trás de “de paris a berlim: deslocamento de questões” — e por que não basta decorar sua definição?","lead":"Nesta aula de leitura, o foco é “de paris a berlim: deslocamento de questões”. Vamos situar o problema no pensamento freudiano, explicitar o raciocínio e observar os limites de sua utilização clínica. O conteúdo abaixo é uma elaboração didática original a partir do tema do texto — não é uma transcrição de aulas de terceiros.","blocks":[{"title":"Antes de interpretar: situação histórica","body":"No relatório de sua viagem de estudos, Freud registra o impacto de Jean-Martin Charcot e da clínica neurológica francesa. A histeria era disputada entre modelos anatômicos, hipóteses funcionais e descrições clínicas; os sintomas nem sempre se ajustavam a lesões detectáveis. O texto pertence à fase pré-psicanalítica: é histórico, não um manifesto do inconsciente freudiano já constituído."},{"title":"Entenda o conceito: De Paris a Berlim: deslocamento de questões","body":"A viagem não transforma Freud imediatamente em psicanalista. Ela amplia seu repertório e o aproxima de debates sobre hipnose, sugestão e sofrimento psíquico. O ponto decisivo é acompanhar a mudança do modo de perguntar: de 'qual lesão?' para 'como descrever o sintoma e seu contexto?'.\n\nRepare que esse recorte não esgota a obra. O exercício aqui é distinguir o que Freud descreve, a interpretação que propõe e o que permanece em aberto. Quando uma hipótese for construída sobre observações clínicas, não a trate automaticamente como regra para toda pessoa ou período histórico."},{"title":"Articulações, controvérsias e limites","body":"A história da psicanálise não começa com um sistema pronto; nasce de controvérsias médicas e clínicas. Diferencie sempre uma observação histórica de uma explicação validada hoje.\n\nO texto foi redigido em 1886 e incluído no primeiro módulo por fidelidade à sequência do sumário."},{"title":"Roteiro de estudo ativo","body":"1. Abra o texto de Freud indicado nas referências e localize os argumentos relacionados a “de paris a berlim: deslocamento de questões”.\n\n2. Escreva com suas palavras a pergunta que motivou o argumento e a resposta provisória oferecida por Freud.\n\n3. Marque uma hipótese e uma observação: elas têm o mesmo estatuto?\n\n4. Compare sua resposta com a seção anterior e registre na área de anotações uma dúvida para retomar mais tarde."}],"example":{"title":"Situação para pensar, sem diagnosticar","body":"Considere alguém com uma paralisia funcional. A investigação contemporânea exige avaliação adequada e não permite concluir, com base apenas em um sintoma, que exista um conflito inconsciente específico. O interesse histórico de Freud estava na insuficiência de certas explicações disponíveis.\n\nAgora retome o foco desta aula: de paris a berlim: deslocamento de questões. Que novas perguntas ele permite formular sem oferecer uma resposta pronta?"},"terms":[{"term":"Histeria","desc":"Categoria histórica de sintomas e organizações clínicas, com sentidos variáveis conforme a época."},{"term":"Charcot","desc":"Neurologista francês cujas aulas influenciaram a formação de Freud."}],"quiz":{"question":"Qual cuidado é essencial ao estudar “de paris a berlim: deslocamento de questões” nesta obra?","options":["Examinar o argumento no contexto de 1886, distinguindo hipótese, exemplos e limites da interpretação.","Tomar qualquer caso citado como demonstração de uma lei psicológica universal.","Usar o conceito como diagnóstico imediato de pessoas reais, dispensando associações e contexto."],"correct":0,"feedback":"O tópico “De Paris a Berlim: deslocamento de questões” exige localizar a hipótese no texto, acompanhar sua construção e reconhecer o que ela não demonstra. A formulação histórica não substitui avaliação clínica atual."},"refs":["Freud (1886) — Relatório dos meus Estudos em Paris e Berlim. Verifique a tradução e a edição utilizada.","Freud, S. — Obras completas; compare a organização cronológica e notas editoriais da edição consultada."]}};
