const LACAN_MODULE_PREV={"lac_m1":"Freud como ponto de partida: que inconsciente é este que aparece na fala?","lac_m2":"Aprender a ouvir a cadeia significante antes de visualizar seus esquemas.","lac_m3":"Identificação, imagem e função simbólica: relações sem psicologia de estágios rígidos.","lac_m4":"Falta e desejo não são nomes para deficiências pessoais: são problemas conceituais específicos.","lac_m5":"Ler a clínica sem reduzir pessoas a rótulos; distinguir formulações de épocas diferentes.","lac_m6":"Distinguir os registros e entender por que se articulam sem virar três caixinhas psicológicas.","lx_m07":"Contexto histórico, retorno a Freud, pequeno outro, grande Outro e sujeito dividido.","lx_m08":"Das necessidades endereçadas ao Outro à estrutura da fantasia e ao grafo do desejo.","lx_m09":"Inconsciente, repetição, transferência e pulsão em 1964, com olhar e voz como objetos a.","lx_m10":"O Seminário X, a relação da angústia com a falta e as distinções entre acting out e passagem ao ato.","lx_m11":"Schreber, foraclusão, Nome-do-Pai e deslocamentos da teoria da psicose.","lx_m12":"A prática analítica como problema de posição, endereçamento e responsabilidade.","lx_m13":"Matemas, lugares, permutações e laço social no Seminário XVII.","lx_m14":"Seminários XX e XXIII: fórmulas, modalidades de gozo e topologia do sinthoma."};
function applyLacanReaderUpdates(){
 const found=courses.find(x=>x.id==='seminarios-lacanianos');
 if(found){
  for(const m of found.modules){
   const seedModule=window.START_COURSES.find(x=>x.id==='seminarios-lacanianos')?.modules.find(x=>x.id===m.id);
   if(seedModule&&(!m.description||m.description===LACAN_MODULE_PREV[m.id])){
     // Conserva descrições de módulos personalizadas.
     if(seedModule.description)m.description=seedModule.description;
   }
   for(const l of m.lessons){const p=LACAN_READER_PATCHES[l.id];if(!p)continue;
     if(l.lead===p.before.lead) l.lead=p.after.lead;
     if(l.hook===p.before.hook) l.hook=p.after.hook;
     if(JSON.stringify(l.blocks||[])===JSON.stringify(p.before.blocks||[]))l.blocks=clone(p.after.blocks);
     if(!l.atelierBridge)l.atelierBridge=clone(p.after.atelierBridge);
     l.minutes=Math.max(Number(l.minutes)||0,p.after.minutes||12);
   }
  }
 }
}
