function save(){try{localStorage.setItem(KEYS.courses,JSON.stringify(courses));localStorage.setItem(KEYS.progress,JSON.stringify(progress));localStorage.setItem(KEYS.notes,JSON.stringify(notes));localStorage.setItem(KEYS.quiz,JSON.stringify(quizData));localStorage.setItem(KEYS.last,JSON.stringify(activeCourse));localStorage.setItem(KEYS.theme,JSON.stringify(theme));}catch(e){toast('Não foi possível salvar no navegador. Exporte um backup para preservar o trabalho.')}}
function esc(v){return String(v??'').replace(/[&<>"']/g,ch=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[ch]))}
function prose(s){return String(s||'').split(/\n\s*\n/).filter(Boolean).map(p=>'<p>'+esc(p).replace(/\n/g,'<br>')+'</p>').join('')}
function course(){return courses.find(x=>x.id===activeCourse)||courses[0]};
function allLessons(c=course()){return (c.modules||[]).flatMap(m=>m.lessons||[])};
function loc(lid,c=course()){for(const m of c.modules||[]){const l=(m.lessons||[]).find(x=>x.id===lid);if(l)return {m,l}}return null}
function doneId(lid){return activeCourse+'::'+lid}
function isDone(lid){return !!progress[doneId(lid)]}
function percentage(c=course()){let arr=allLessons(c);return arr.length?Math.round(arr.filter(l=>progress[c.id+'::'+l.id]).length*100/arr.length):0}
function refreshNav(){let c=course();activeCourse=c.id;$('#courseBtnText').textContent=(c.icon||'✦')+'  '+c.title;let total=allLessons().length,finished=allLessons().filter(l=>isDone(l.id)).length;$('#progressLabel').textContent=`${finished} de ${total} aulas concluídas`;$('#progressPct').textContent=percentage()+'%';$('#sideProgress').style.width=percentage()+'%';$('#courseBtn').setAttribute('aria-expanded','false');$('#coursePicker').classList.add('hidden');renderSidebar()}
function renderSidebar(){let c=course();const q=$('#sidebarSearch').value.trim().toLocaleLowerCase('pt-BR');let html=`<button class="side-home ${view==='home'?'active':''}" data-view="home">⌂ &nbsp; Visão geral do curso</button>`;
(c.modules||[]).forEach((m,mi)=>{let lessons=(m.lessons||[]).filter(l=>!q||(l.title+' '+(l.lead||'')).toLocaleLowerCase('pt-BR').includes(q));if(q&&!lessons.length&&!(m.title||'').toLocaleLowerCase('pt-BR').includes(q))return;if(q&&!lessons.length)lessons=m.lessons||[];let isOpen=q||(expanded[m.id]!==undefined?expanded[m.id]:(c.id!=='formacao-freudiana'||mi===0));html+=`<div class="module ${isOpen?'':'closed'}"><div class="module-head"><button class="module-toggle" data-toggle="${esc(m.id)}" aria-expanded="${isOpen}"><span><span class="module-count">MÓDULO ${String(mi+1).padStart(2,'0')} · ${(m.lessons||[]).length} AULAS</span><span class="module-title">${esc(m.title)}</span></span><span class="chev">⌄</span></button><button class="icon-btn" data-editmodule="${esc(m.id)}" title="Editar módulo" aria-label="Editar módulo ${esc(m.title)}">⋯</button></div><div class="module-lessons">`;
lessons.forEach((l,i)=>{html+=`<div class="lesson-row ${view==='lesson'&&activeLesson===l.id?'active':''}"><button class="lesson-link" data-lesson="${esc(l.id)}"><span class="status-dot ${isDone(l.id)?'done':''}">${isDone(l.id)?'✓':''}</span><span class="lesson-txt">${esc(l.title)}</span></button><button class="mini-options" data-editlesson="${esc(l.id)}" title="Editar aula" aria-label="Editar aula ${esc(l.title)}">⋯</button></div>`});html+='</div></div>'});
html+='<button class="sidebar-add" id="addModuleBtn">＋ Adicionar módulo ao curso</button>';$('#sideScroll').innerHTML=html}
function updateBreadcrumb(title){$('#crumbA').textContent=course().title.toUpperCase();$('#crumbB').textContent=title}
function goHome(){view='home';activeLesson=null;render();closeMobile()}
function goLesson(id){if(!loc(id))return;view='lesson';activeLesson=id;selectedAnswer=quizData[doneId(id)]?.selected??null;activeLab=0;kleinStage=0;kleinCompare=false;winStage=0;winCase=-1;winCompare=false;ndState={step:0,path:0,era:0,choice:-1};lcActiveStep=0;languageState={context:0,metaphor:0,assoc:-1,answer:-1,branch:-1,linkCount:2,compare:false};atReset();lxStage=0;lxCompare=false;lxRevealed=false;lxTimeline=0;lxFormula=0;lxBroken='intact';lxExtra=0;lxDisc=({lx_030:0,lx_031:1,lx_032:2,lx_033:3})[id]??0;expanded={...expanded,[loc(id).m.id]:true};render();closeMobile()}
