function fmLensPanel(i){const x=FREUD_MOTION_LENSES[i];return `<div class="fm-explain" id="fmLensExpl" aria-live="polite"><h3>${esc(x.name)}</h3><div class="fm-def-row"><b>Qual pergunta?</b><p>${esc(x.question)}</p></div><div class="fm-def-row"><b>O que investigar?</b><p>${esc(x.observe)}</p></div><div class="fm-def-row"><b>O que não concluir?</b><p>${esc(x.limit)}</p></div></div>`}
function fmChronoPanel(i){const x=FREUD_MOTION_STEPS[i];return `<div class="fm-timecard" id="fmTimeCard" aria-live="polite"><div class="fm-dateline">${esc(x.year)} &nbsp;·&nbsp; ${esc(x.place)}</div><h3>${esc(x.title)}</h3><p>${esc(x.detail)}</p><p class="fm-learning"><strong>O que perceber:</strong> ${esc(x.learning)}</p></div>`}
function renderFreudMotion(id){
 if(id==='freud_a001')return `<section class="freud-motion" id="freudMotionA" aria-label="Laboratório interativo: três maneiras de investigar um sintoma"><div class="fm-head"><div><div class="fm-kicker">◆ EXPERIÊNCIA INTERATIVA &nbsp; 01 / 02</div><h2>Um sintoma. Três maneiras de perguntar.</h2><p>Imagine uma pessoa dizendo: “Não consigo mover bem meu braço”. Clique nas diferentes formas de investigação e observe como <strong>cada pergunta produz informações distintas</strong> — sem revelar automaticamente a causa.</p></div><span class="fm-badge">2–3 MIN</span></div><div class="fm-body"><div class="fm-stage" id="fmLensSVG">${fmLensesSVG(fmLens)}</div><div class="fm-pick-label">ESCOLHA A PERGUNTA QUE QUER INVESTIGAR</div><div class="fm-picks">${FREUD_MOTION_LENSES.map((x,j)=>`<button type="button" class="fm-pick ${fmLens===j?'fm-active':''}" data-fmlens="${j}" aria-pressed="${fmLens===j}"><span class="fm-pick-num">0${j+1}</span><strong>${esc(x.short)}</strong></button>`).join('')}</div>${fmLensPanel(fmLens)}<div class="fm-check"><h3>Você consegue evitar um salto de interpretação?</h3><p>Se um exame não encontra imediatamente uma lesão que explique um sintoma, qual seria a conclusão mais cuidadosa?</p><div class="fm-checkchoices">${['“O sintoma é fingido ou imaginário.”','“O problema deve ser exclusivamente psíquico.”','“Ainda é preciso investigar; a ausência de uma explicação inicial não determina a causa.”'].map((x,j)=>`<button type="button" data-fmanswer="${j}" class="${fmAnswer===j?'fm-chosen':''}" aria-pressed="${fmAnswer===j}">${esc(x)}</button>`).join('')}</div><div class="fm-feedback ${fmAnswer!==null&&fmAnswer!==2?'fm-error':''}" id="fmAnswerFeedback" role="status">${fmAnswer===null?'Escolha uma alternativa para ver o comentário.':fmAnswer===2?'Correto. A descrição e a investigação de um sintoma não autorizam concluir sua causa de antemão.':'Ainda não. Uma hipótese não deve ser tratada como conclusão. A investigação médica e clínica continua necessária.'}</div></div></div><div class="fm-bottom"><div class="fm-notice"><strong>O que esta animação quer ensinar?</strong> A mesma manifestação pode suscitar perguntas diferentes. Ela não transforma a histeria histórica em diagnóstico contemporâneo, nem sugere que Charcot ou Freud já possuíssem uma explicação única. Este diagrama é uma construção pedagógica, não um esquema de Freud.</div></div></section>`;
 if(id==='freud_a002')return `<section class="freud-motion" id="freudMotionB" aria-label="Linha do tempo interativa da formação de Freud"><div class="fm-head"><div><div class="fm-kicker">◆ EXPERIÊNCIA INTERATIVA &nbsp; 02 / 02</div><h2>A psicanálise não surgiu de uma só vez.</h2><p>Controle a sequência e veja o que Freud estava estudando em cada momento. <strong>As datas importam:</strong> os conceitos de 1900 não estavam prontos durante a viagem de 1886.</p></div><span class="fm-badge">3 MIN</span></div><div class="fm-body"><div class="fm-timeline"><div class="fm-track" aria-hidden="true"><div class="fm-track-fill" id="fmTrackFill" style="width:${fmStep/3*100}%"></div></div><div class="fm-stations">${FREUD_MOTION_STEPS.map((x,j)=>`<button type="button" data-fmtime="${j}" class="fm-station ${j<=fmStep?'fm-reached':''} ${j===fmStep?'fm-current':''}" aria-current="${j===fmStep?'step':'false'}"><span class="fm-year">${esc(x.year)}</span><span class="fm-dot"></span><span class="fm-place">${esc(x.place)}</span></button>`).join('')}</div></div>${fmChronoPanel(fmStep)}<div class="fm-controls"><button type="button" class="btn sm" data-fmcontrol="prev" ${fmStep===0?'disabled':''}>← Anterior</button><button type="button" class="btn sm primary" id="fmPlayBtn" data-fmcontrol="play">▶ Reproduzir</button><button type="button" class="btn sm" data-fmcontrol="next" ${fmStep===3?'disabled':''}>Próximo →</button><span class="fm-counter" id="fmCounter">ETAPA ${fmStep+1} / 04</span></div><p class="fm-reason"><strong>Experimente:</strong> escolha “Berlim” e depois “1900”. Compare as atividades neurológicas de 1886 com a teoria dos sonhos elaborada anos mais tarde. A linha é uma seleção didática, não uma história completa ou inevitável da psicanálise.</p></div><div class="fm-bottom"><div class="fm-notice"><strong>Leitura histórica:</strong> o relatório de Freud registra Paris e Berlim entre 1885 e 1886. As etapas de 1895 e 1900 mostram desdobramentos posteriores, não acontecimentos narrados nesse relatório. Visualização didática baseada na cronologia das obras.</div></div></section>`;
 return '';
}
function fmSelectLens(i){fmLens=i;const el=document.getElementById('freudMotionA');if(!el)return;document.getElementById('fmLensSVG').innerHTML=fmLensesSVG(i);document.getElementById('fmLensExpl').outerHTML=fmLensPanel(i);el.querySelectorAll('[data-fmlens]').forEach((b,j)=>{b.classList.toggle('fm-active',j===i);b.setAttribute('aria-pressed',String(j===i))})}
function fmChooseAnswer(i){fmAnswer=i;const el=document.getElementById('freudMotionA');if(!el)return;el.querySelectorAll('[data-fmanswer]').forEach((b,j)=>{b.classList.toggle('fm-chosen',j===i);b.setAttribute('aria-pressed',String(j===i))});const feedback=document.getElementById('fmAnswerFeedback');feedback.classList.toggle('fm-error',i!==2);feedback.textContent=i===2?'Correto. A descrição e a investigação de um sintoma não autorizam concluir sua causa de antemão.':'Ainda não. Uma hipótese não deve ser tratada como conclusão. A investigação médica e clínica continua necessária.'}
function fmUpdateTime(i){fmStep=Math.max(0,Math.min(3,i));const el=document.getElementById('freudMotionB');if(!el){fmStop();return}el.querySelectorAll('[data-fmtime]').forEach((b,j)=>{b.classList.toggle('fm-reached',j<=fmStep);b.classList.toggle('fm-current',j===fmStep);b.setAttribute('aria-current',j===fmStep?'step':'false')});document.getElementById('fmTrackFill').style.width=(fmStep/3*100)+'%';document.getElementById('fmTimeCard').outerHTML=fmChronoPanel(fmStep);document.getElementById('fmCounter').textContent=`ETAPA ${fmStep+1} / 04`;el.querySelector('[data-fmcontrol="prev"]').disabled=fmStep===0;el.querySelector('[data-fmcontrol="next"]').disabled=fmStep===3;if(fmStep===3&&fmTimer){fmStop();fmSyncPlay()}}
function fmSyncPlay(){const b=document.getElementById('fmPlayBtn');if(b){b.textContent=fmTimer?'Ⅱ Pausar':'▶ Reproduzir';b.setAttribute('aria-pressed',String(!!fmTimer))}}
function fmControl(type){if(type==='prev'||type==='next'){fmStop();fmUpdateTime(fmStep+(type==='prev'?-1:1));fmSyncPlay();return}if(type==='play'){if(fmTimer){fmStop();fmSyncPlay();return}if(fmStep===3)fmUpdateTime(0);fmTimer=setInterval(()=>{if(!document.getElementById('freudMotionB')){fmStop();return}fmUpdateTime(fmStep+1)},3600);fmSyncPlay()}}


// Três experiências sobre texto histórico; o movimento representa hipóteses, não dados clínicos.
const ND_STEPS=[
 {title:'1 · Uma ideia difícil de sustentar',body:'No modelo de 1894, uma representação — ideia, lembrança, desejo — entra em oposição dolorosa com o eu. Exemplo: a pessoa quer descansar, mas se exige não sentir cansaço.',limit:'A incompatibilidade pode existir sem qualquer sintoma. O exemplo não define doença.'},
 {title:'2 · A tentativa de afastar',body:'O eu tenta deixar de pensar no conteúdo incompatível. Freud procura explicar efeitos psíquicos que escapam à vontade consciente: querer esquecer NÃO equivale a escolher ter um sintoma.',limit:'Aqui “defesa” não deve ser traduzida por fingimento, mentira ou manipulação.'},
 {title:'3 · Ideia e afeto não são a mesma coisa',body:'Freud hipotetiza que a representação pode perder intensidade consciente, enquanto a excitação a ela ligada ganha outro destino. É sua hipótese de “quantidade de afeto”.',limit:'A quantidade não foi medida; os pontos e setas são uma metáfora pedagógica.'},
 {title:'4 · O problema pode reaparecer',body:'A defesa não apagaria necessariamente todos os efeitos do conflito. A pergunta passa a ser: que destino Freud supõe para o afeto em cada quadro histórico? Essa é a próxima aula.',limit:'Não conclua que todo sofrimento atual deriva de uma lembrança recalcada.'}
];
const ND_PATHS=[
 {title:'Conversão (hipótese freudiana)',short:'A conversão',body:'Em alguns quadros então chamados de histeria, Freud supõe que a excitação ligada à representação incompatível encontra expressão em manifestações motoras ou sensoriais. O caminho destacado leva do conflito ao CORPO.',caution:'Uma manifestação corporal real não prova conversão. É necessário investigar causas médicas e contexto. O SVG não mostra vias anatômicas.',dest:'Expressão corporal',note:'Esfera somática',c:'#C79B67'},
 {title:'Deslocamento (hipótese freudiana)',short:'O deslocamento',body:'Nas obsessões e em algumas fobias que investiga, Freud propõe que o afeto fica no campo das IDEIAS, ligado a uma representação substituta. O resultado seria uma preocupação ou ideia investida de afeto desproporcional.',caution:'Isso não é explicação universal de pensamentos intrusivos e nem diagnóstico do transtorno obsessivo-compulsivo.',dest:'Outra representação',note:'Esfera psíquica',c:'#8DB8AE'},
 {title:'Compare os dois caminhos',short:'Comparar',body:'O ponto de partida é parecido: uma ideia incompatível e uma tentativa de defesa. O que muda é o destino TEÓRICO da excitação: expressão corporal, no primeiro percurso; ligação a outra ideia, no segundo.',caution:'Essas são distinções da hipótese de 1894, não categorias para rotular pessoas. A psicose, que Freud também discute, é tratada na aula 3.',dest:'Diferentes destinos',note:'Dois percursos',c:'#B7A0D7'}
];
const ND_ERAS=[
 {yr:'1894',title:'A primeira hipótese: defesa e diferentes destinos',body:'No texto de 1894, Freud organiza fenômenos diversos em torno da defesa contra uma representação incompatível. Descreve conversão, deslocamento e uma hipótese de rejeição mais radical ligada a certos estados alucinatórios.',limit:'É um ensaio de teoria, não uma explicação clínica conclusiva de todas as psicoses.'},
 {yr:'1896',title:'O complemento: paranoia e etiologia',body:'Freud retoma a defesa em um novo artigo, investiga a neurose obsessiva, discute um caso de paranoia e apresenta hipóteses etiológicas específicas envolvendo experiências sexuais infantis. São afirmações historicamente situadas.',limit:'A ligação causal universal que Freud tentou defender não é considerada estabelecida. Um relato clínico não é regra para todas as pessoas.'},
 {yr:'1897 →',title:'A revisão e as perguntas que ficaram',body:'Em setembro de 1897, Freud registra suas dúvidas sobre a teoria causal anterior. Suas reflexões evoluem para outros problemas, como fantasia e realidade psíquica. Textos posteriores reformulam a diferença entre neurose e psicose.',limit:'Rever uma teoria não significa negar abusos reais. Tampouco permite projetar a foraclusão lacaniana diretamente sobre 1894.'}
];
let ndState={step:0,path:0,era:0,choice:-1};
function ndFrame(nodes,connections,active, labels){return `<svg viewBox="0 0 700 176" role="img" aria-label="Visualização didática das hipóteses de Freud"><g>${connections.map((p,i)=>`<path d="${p}" class="nd-line ${active.includes(i)?'active':''}"/>`).join('')}</g>${nodes.map((n,i)=>`<rect x="${n[0]}" y="${n[1]}" width="${n[2]}" height="${n[3]}" rx="15" class="nd-n ${labels.includes(i)?'active':''}"/><text x="${n[0]+n[2]/2}" y="${n[1]+n[3]/2+4}" text-anchor="middle" class="nd-svgtext">${n[4]}</text>`).join('')}</svg>`}
function ndStepVisual(i){const nodes=[[16,59,151,61,'Conflito'],[188,59,151,61,'Defesa'],[360,59,151,61,'Afeto'],[531,59,152,61,'Questão']];const cx=[167,339,511];const lines=cx.map(v=>`M${v} 90 L${v+21} 90`);return ndFrame(nodes,lines,Array.from({length:Math.max(0,i)},(_,j)=>j),nodes.map((_,j)=>j===i?j:-1))}
function ndPathVisual(i){return `<svg viewBox="0 0 700 240" role="img" aria-label="Comparação das duas rotas hipotéticas de defesa"><rect x="10" y="74" width="160" height="83" rx="14" class="nd-n active"/><text x="90" y="110" text-anchor="middle" class="nd-svgtext">Representação</text><text x="90" y="131" text-anchor="middle" class="nd-svgsub">e afeto</text><path d="M170 115 L235 115" class="nd-line active"/><rect x="235" y="76" width="137" height="80" rx="14" class="nd-n active"/><text x="303" y="112" text-anchor="middle" class="nd-svgtext">Defesa</text><text x="303" y="133" text-anchor="middle" class="nd-svgsub">(hipótese)</text><path d="M372 115 C413 115 405 55 468 55" class="nd-line ${i===0||i===2?'active':''}"/><path d="M372 115 C413 115 405 189 468 189" class="nd-line ${i===1||i===2?'active':''}"/><rect x="469" y="12" width="220" height="84" rx="14" class="nd-n ${i===0||i===2?'active':''}"/><text x="579" y="44" text-anchor="middle" class="nd-svgtext">Conversão</text><text x="579" y="65" text-anchor="middle" class="nd-svgsub">expressão corporal</text><rect x="469" y="146" width="220" height="84" rx="14" class="nd-n ${i===1||i===2?'active':''}"/><text x="579" y="176" text-anchor="middle" class="nd-svgtext">Deslocamento</text><text x="579" y="197" text-anchor="middle" class="nd-svgsub">outra ideia</text></svg>`}
function ndEraVisual(i){return `<svg viewBox="0 0 700 138" role="img" aria-label="Linha de tempo das hipóteses 1894, 1896 e 1897"><path d="M100 69 L600 69" class="nd-line ${i>0?'active':''}"/>${ND_ERAS.map((v,j)=>{let x=[100,350,600][j];return `<circle cx="${x}" cy="69" r="29" class="nd-n ${i===j?'active':''}"/><text x="${x}" y="75" class="nd-svgtext" text-anchor="middle">${v.yr}</text><text x="${x}" y="123" text-anchor="middle" class="nd-svgsub">${['Proposta','Ampliação','Revisão'][j]}</text>`}).join('')}</svg>`}
function renderND(id){if(id==='freud_a003'){const i=ndState.step,x=ND_STEPS[i];return `<section class="lesson-step"><div class="step-caption">✳ LABORATÓRIO VISUAL · AULA 1</div><h2>Como Freud constrói a hipótese de defesa?</h2><p>Você estudou as palavras “representação”, “eu” e “defesa”. Agora clique nas etapas. Cada clique revela <b>uma pergunta teórica</b>, e não uma etapa obrigatória da vida de qualquer pessoa.</p><div class="nd-lab"><div class="nd-bar"><div class="nd-kicker">Um modelo de 1894, reconstruído para ensino</div><h3>O que é observado? O que é inferido?</h3><p>O percurso animado é didático. As setas não são prova de causalidade.</p></div><div class="nd-nav">${ND_STEPS.map((v,j)=>`<button data-nd="step" data-ndindex="${j}" class="${i===j?'active':''}" aria-pressed="${i===j}"><span>ETAPA ${j+1}</span>${['A ideia difícil','A tentativa de defesa','O destino do afeto','A pergunta sobre o sintoma'][j]}</button>`).join('')}</div><div class="nd-flow" id="ndGraphic">${ndStepVisual(i)}</div><div class="nd-card" id="ndExplain" aria-live="polite"><h4>${x.title}</h4><p>${x.body}</p><div class="nd-alert">Cuidado: ${x.limit}</div></div><div class="nd-progress">Explore os quatro pontos. <strong>${i+1} de 4</strong> · toque em outra etapa para comparar.</div></div></section>`}
if(id==='freud_a004'){const i=ndState.path,x=ND_PATHS[i];return `<section class="lesson-step"><div class="step-caption">✳ LABORATÓRIO VISUAL · AULA 2</div><h2>Uma defesa, diferentes destinos hipotéticos</h2><p>Selecione um caminho. Observe que a representação e a defesa iniciais permanecem: o que muda é <b>o destino imaginado por Freud para o afeto</b>. Você poderá comparar sem dar nome clínico a ninguém.</p><div class="nd-lab"><div class="nd-bar"><div class="nd-kicker">Comparação de mecanismos no artigo de 1894</div><h3>O afeto fica onde, segundo o modelo?</h3><p>Duas rotas propostas historicamente, não vias físicas ou uma simulação diagnóstica.</p></div><div class="nd-three">${ND_PATHS.map((v,j)=>`<button data-nd="path" data-ndindex="${j}" class="${i===j?'active':''}" aria-pressed="${i===j}">${v.short}<small>${['No corpo (modelo)','Em outra ideia (modelo)','O que muda?'][j]}</small></button>`).join('')}</div><div class="nd-flow" id="ndGraphic">${ndPathVisual(i)}</div><div class="nd-card" id="ndExplain" aria-live="polite"><h4>${x.title}</h4><p>${x.body}</p><div class="nd-alert">Limite: ${x.caution}</div></div></div></section>`}
if(id==='freud_a005'){const i=ndState.era,x=ND_ERAS[i];return `<section class="lesson-step"><div class="step-caption">✳ LABORATÓRIO VISUAL · AULA 3</div><h2>O que Freud afirmou — e depois precisou revisar?</h2><p>Troque o ano e observe como uma hipótese muda. O objetivo é aprender a <b>separar textos, argumentos e limites</b>.</p><div class="nd-lab"><div class="nd-bar"><div class="nd-kicker">Uma linha do tempo para ler criticamente</div><h3>Três momentos, três perguntas</h3><p>Os anos indicam publicações e correspondência, não etapas rígidas de uma única teoria.</p></div><div class="nd-three">${ND_ERAS.map((v,j)=>`<button data-nd="era" data-ndindex="${j}" class="${i===j?'active':''}" aria-pressed="${i===j}">${v.yr}<small>${['O ensaio inicial','Ampliação e paranoia','Revisão crítica'][j]}</small></button>`).join('')}</div><div class="nd-flow" id="ndGraphic">${ndEraVisual(i)}</div><div class="nd-card" id="ndExplain" aria-live="polite"><h4>${x.title}</h4><p>${x.body}</p><div class="nd-alert">Limite de leitura: ${x.limit}</div></div><div class="nd-progress">Verifique o que mudou de um documento para outro. Depois responda à questão.</div><div class="nd-answer-grid">${['Toda alucinação hoje confirma a hipótese de 1894.','Freud investigou hipóteses diferentes em momentos diferentes; suas categorias não equivalem às atuais.','Rever a teoria da sedução significa provar que não existem abusos reais.'].map((v,j)=>`<button data-nd="choice" data-ndindex="${j}" class="${ndState.choice===j?'chosen':''}">${j+1}. ${v}</button>`).join('')}</div><div id="ndAnswer" aria-live="polite">${ndState.choice<0?'':ndAnswerFeedback(ndState.choice)}</div></div></section>`}
return ''}
function ndAnswerFeedback(j){return `<div class="nd-feedback"><strong>${j===1?'Correto.':'Ainda não.'}</strong> ${j===1?'A leitura histórica exige distinguir as hipóteses e seus contextos, evitando diagnósticos precipitados.':'Volte aos três anos: uma formulação histórica não explica todos os casos, e uma revisão teórica não invalida relatos reais de violência.'}</div>`}
function ndSelect(type,index){if(!['step','path','era','choice'].includes(type)||!Number.isInteger(index))return;const max={step:4,path:3,era:3,choice:3}[type];if(index<0||index>=max)return;ndState[type]=index;if(!['freud_a003','freud_a004','freud_a005'].includes(activeLesson))return;
if(type==='choice'){$('#ndAnswer').innerHTML=ndAnswerFeedback(index);document.querySelectorAll('button[data-nd="choice"]').forEach(b=>b.classList.toggle('chosen',Number(b.dataset.ndindex)===index));return;}
let svg=document.getElementById('ndGraphic'),box=document.getElementById('ndExplain');if(!svg||!box)return;
if(type==='step'){const v=ND_STEPS[index];svg.innerHTML=ndStepVisual(index);box.innerHTML=`<h4>${v.title}</h4><p>${v.body}</p><div class="nd-alert">Cuidado: ${v.limit}</div>`;const stat=document.querySelector('.nd-progress strong');if(stat)stat.textContent=`${index+1} de 4`}
if(type==='path'){const v=ND_PATHS[index];svg.innerHTML=ndPathVisual(index);box.innerHTML=`<h4>${v.title}</h4><p>${v.body}</p><div class="nd-alert">Limite: ${v.caution}</div>`}
if(type==='era'){const v=ND_ERAS[index];svg.innerHTML=ndEraVisual(index);box.innerHTML=`<h4>${v.title}</h4><p>${v.body}</p><div class="nd-alert">Limite de leitura: ${v.limit}</div>`}
document.querySelectorAll('button[data-nd="'+type+'"]').forEach(b=>{const on=Number(b.dataset.ndindex)===index;b.classList.toggle('active',on);b.setAttribute('aria-pressed',String(on))});
}

function hasNeuroMotion(l){return activeCourse==='formacao-freudiana'&&['freud_a003','freud_a004','freud_a005'].includes(l.id)}
function hasFreudMotion(l){return activeCourse==='formacao-freudiana' && ['freud_a001','freud_a002'].includes(l.id)}

