 return `<svg viewBox="0 0 830 277" role="img" aria-label="Discurso da histérica: agente sujeito barrado, outro S1, verdade objeto a, produção S2"><path class="lc-ds-arrow" d="M310 73 H520 m-13 -8 13 8 -13 8"/><path class="lc-ds-bar" d="M100 132 H300 M525 132 H725"/>${options.map((x,j)=>`<g class="lc-disc-slot ${j===index?'chosen':''}" ><rect x="${coords[j][0]-108}" y="${coords[j][1]-41}" rx="12" width="216" height="83"/><text class="lc-slot-symbol" x="${coords[j][0]}" y="${coords[j][1]-5}" text-anchor="middle">${x[0]}</text><text class="lc-slot-label" x="${coords[j][0]}" y="${coords[j][1]+24}" text-anchor="middle">${x[1]}</text></g>`).join('')}</svg>`;
