function renderLacanExpansion(l){if(activeCourse!=='seminarios-lacanianos'||!l.lx)return '';
 let a=l.lx.steps,step=a[lxStage],special=l.lx.module==='lx_m13'?'discurso':l.id==='lx_009'?'grafo':l.id==='lx_034'?'sexuacao':['lx_037','lx_038','lx_039'].includes(l.id)?'borro':'geral';
 let tools='';
 if(special==='discurso')tools=`<div class="lx-special"><p>Gire os matemas mantendo os quatro lugares fixos. A mudança de discurso não muda o desenho das posições.</p><div class="lx-actions">${LX_DISCOURSES.map((d,i)=>`<button type="button" class="${lxDisc===i?'selected':''}" data-lxdisc="${i}">${esc(d.name)}</button>`).join('')}</div><div class="lx-special-answer" aria-live="polite"><b>${esc(LX_DISCOURSES[lxDisc].name)}</b> · ${esc(LX_DISCOURSES[lxDisc].reading)}</div></div>`;
 if(special==='grafo')tools=`<div class="lx-special"><p>Construa seis camadas. Só avance quando conseguir dizer o que a etapa anterior acrescenta. Não é o grafo original.</p><div class="lx-actions">${LX_GRAPH_STEPS.map((x,i)=>`<button type="button" data-lxgraph="${i}" class="${lxTimeline===i?'selected':''}">${i+1}</button>`).join('')}</div><div class="lx-special-answer" aria-live="polite"><b>${esc(LX_GRAPH_STEPS[lxTimeline][0])}</b><p>${esc(LX_GRAPH_STEPS[lxTimeline][1])}</p><div class="lx-nav"><button type="button" data-lxgraph="${Math.max(0,lxTimeline-1)}" ${lxTimeline===0?'disabled':''}>← Anterior</button><button type="button" data-lxgraph="${Math.min(5,lxTimeline+1)}" ${lxTimeline===5?'disabled':''}>Próximo →</button></div></div></div>`;
 if(special==='sexuacao')tools=`<div class="lx-special"><p>Toque nas quatro fórmulas; observe os quantificadores e as negações. O esquema não classifica pessoas.</p><div class="lx-actions">${['∃x ¬Φ(x)','∀x Φ(x)','¬∃x ¬Φ(x)','¬∀x Φ(x)'].map((x,i)=>`<button class="lx-formula-btn ${lxFormula===i?'selected':''}" type="button" data-lxformula="${i}">${x}</button>`).join('')}</div><div class="lx-special-answer" aria-live="polite">${LX_FORMULA_DESCS[lxFormula]}</div></div>`;
 if(special==='borro')tools=`<div class="lx-special"><p>Experimente retirar um dos componentes. Em uma ligação borromeana verdadeira, os dois restantes se desvinculam. A imagem abaixo apenas ilustra essa ideia.</p><div class="lx-actions">${[['intact','Intacto'],['R','Romper R'],['S','Romper S'],['I','Romper I']].map(([v,t])=>`<button type="button" class="${lxBroken===v?'selected':''}" data-lxbreak="${v}">${t}</button>`).join('')}</div><div class="lx-special-answer" aria-live="polite">${lxBroken==='intact'?'R = Real, S = Simbólico, I = Imaginário. Os três componentes são pensados numa amarração cuja propriedade não se deduz de círculos sobrepostos.':`Rompendo o componente ${lxBroken}, a animação separa os outros dois. É uma metáfora visual da propriedade borromeana, não uma prova topológica em 3D.`}</div></div>`;
 return `<section class="lesson-step lx-lab" id="lacExpansionLab" aria-label="Laboratório interativo desta aula"><div class="lx-top"><span>✧ ATELIER · EXPERIÊNCIA INTERATIVA</span><span>${(lxStage+1)} / 3</span></div><h2>${esc(l.lx.label)} <small>· ${esc(l.title)}</small></h2><p class="lx-lead">Investigue três dimensões do argumento antes de responder. O modelo não é um teste clínico nem um desenho original de Lacan.</p>
 <div class="lx-stage-tabs">${a.map((x,i)=>`<button type="button" data-lxstage="${i}" class="${i===lxStage?'selected':''}" aria-pressed="${i===lxStage}"><span>${String(i+1).padStart(2,'0')}</span>${esc(x.title)}</button>`).join('')}</div>
 <div class="lx-visual">${lxVisual(l)}</div>${tools}
 ${lxExtraPanel(l)}
 <div class="lx-reading" aria-live="polite"><div class="lx-reading-tag">ETAPA ${lxStage+1} · ${esc(step.title)}</div><p>${esc(LX_SNIPPET(step.text,480))}</p><button type="button" data-lxreveal="1">${lxRevealed?'Ocultar aprofundamento ↑':'Entender melhor esta etapa ↓'}</button>${lxRevealed?`<div class="lx-more">${prose(step.text)}</div>`:''}</div>
 <div class="lx-compare-row"><button type="button" data-lxcompare="1">${lxCompare?'Fechar comparação ↑':'Comparar os três momentos ↗'}</button><span>Escolha uma etapa para mudar o foco do diagrama.</span></div>
 ${lxCompare?`<div class="lx-comparison">${a.map((x,i)=>`<div><b>${i+1}. ${esc(x.title)}</b><p>${esc(LX_SNIPPET(x.text,220))}</p></div>`).join('')}</div>`:''}
 <div class="lx-note"><b>Limite desta experiência</b><span>O diagrama é uma interpretação pedagógica. Leia os textos indicados na aula para estudar os matemas e suas mudanças históricas com rigor.</span></div></section>`;
}
function lxHandle(b){let d=b.dataset;
 if(d.lxstage!==undefined){lxStage=Math.max(0,Math.min(2,Number(d.lxstage)||0));lxRevealed=false;}
 else if(d.lxcompare!==undefined){lxCompare=!lxCompare;}
 else if(d.lxreveal!==undefined){lxRevealed=!lxRevealed;}
 else if(d.lxdisc!==undefined){lxDisc=Math.max(0,Math.min(3,Number(d.lxdisc)||0));}
 else if(d.lxgraph!==undefined){lxTimeline=Math.max(0,Math.min(5,Number(d.lxgraph)||0));}
 else if(d.lxformula!==undefined){lxFormula=Math.max(0,Math.min(3,Number(d.lxformula)||0));}
 else if(d.lxbreak!==undefined){lxBroken=['R','S','I'].includes(d.lxbreak)?d.lxbreak:'intact';}
 else if(d.lxextra!==undefined){lxExtra=Math.max(0,Math.min(3,Number(d.lxextra)||0));}
 else return false;
 const box=document.getElementById('lacExpansionLab'),ctx=loc(activeLesson);if(box&&ctx){let att=Object.keys(d).find(k=>k.startsWith('lx'));let val=att&&b.dataset[att];box.outerHTML=renderLacanExpansion(ctx.l);if(att){const after=document.querySelector(`[data-${att.replace(/([A-Z])/g,'-$1').toLowerCase()}="${CSS.escape(val)}"]`);try{after?.focus({preventScroll:true})}catch(e){}}}
 return true;
}


// Laboratórios Winnicott: cada aula tem etapas + situações alternativas + comparação.
let winStage=0,winCase=-1,winCompare=false;
const WL_ID='seminarios-winnicottianos';
function wlSVG(l){
 const w=l.winnLab,st=Math.min(2,Math.max(0,winStage)),kind=w.kind;
 const node=(x,y,label,i,rx=86,ry=46)=>`<ellipse class="wl-node ${i===st?'active':''}" cx="${x}" cy="${y}" rx="${rx}" ry="${ry}"/><text class="wl-text" x="${x}" y="${y+5}">${esc(label)}</text>`;
 const path=(d)=>`<path class="wl-connector" d="${d}"/>`;
 let inner='';
 const stepLabel=['01','02','03'];
 if(kind==='history'){
  inner=path('M150 140L610 140')+[140,380,620].map((x,i)=>`<circle cx="${x}" cy="140" r="43" class="wl-node ${i===st?'active':''}"/><text x="${x}" y="148" class="wl-text">${i+1}</text><text x="${x}" y="215" class="wl-text wl-small">${esc(w.steps[i])}</text>`).join('');
 }else if(kind==='mature'){
  inner=path('M170 135H590')+[160,380,600].map((x,i)=>`<rect class="wl-node ${i===st?'active':''}" x="${x-98}" y="88" width="196" height="97" rx="17"/><text x="${x}" y="133" class="wl-text">${esc(['EXPERIÊNCIA','CORPO','MUNDO'][i])}</text><text x="${x}" y="158" class="wl-text wl-small">${esc(w.steps[i].slice(0,25))}</text>`).join('');
 }else if(kind==='care'){
  inner=`<circle class="wl-node ${st===0?'active':''}" cx="160" cy="142" r="69"/><rect class="wl-node ${st===1?'active':''}" x="305" y="88" width="150" height="106" rx="19"/><circle class="wl-node ${st===2?'active':''}" cx="600" cy="142" r="69"/>${path('M229 142H305M455 142H531')}<text class="wl-text" x="160" y="135">BEBÊ</text><text class="wl-text wl-small" x="160" y="154">sinais</text><text class="wl-text" x="380" y="133">AMBIENTE</text><text class="wl-text wl-small" x="380" y="155">observa</text><text class="wl-text" x="600" y="135">RESPOSTA</text><text class="wl-text wl-small" x="600" y="154">ajuste</text>`;
 }else if(kind==='space'){
  inner=`<circle class="wl-node ${st===0?'active':''}" cx="284" cy="138" r="106"/><circle class="wl-node ${st===1?'active':''}" cx="476" cy="138" r="106"/><ellipse class="wl-node ${st===2?'active':'secondary'}" cx="380" cy="138" rx="46" ry="58"/><text class="wl-text wl-small" x="240" y="139">SUBJETIVO</text><text class="wl-text wl-small" x="520" y="139">COMPARTILHADO</text><text x="380" y="142" class="wl-text wl-small">ENTRE</text>`;
 }else if(kind==='cycle'){
  inner=`<circle cx="380" cy="140" r="95" class="wl-connector" style="stroke-dasharray:9 10"/>`+[[380,48],[485,196],[275,196]].map(([x,y],i)=>`<circle cx="${x}" cy="${y}" r="59" class="wl-node ${st===i?'active':''}"/><text x="${x}" y="${y+5}" class="wl-text">${esc(['CONFLITO','CONTINUIDADE','REPARAÇÃO'][i])}</text>`).join('');
 }else if(kind==='triangle'){
  inner=path('M380 57L200 202H560Z')+[[380,59],[200,200],[560,200]].map(([x,y],i)=>`<circle class="wl-node ${st===i?'active':''}" cx="${x}" cy="${y}" r="55"/><text class="wl-text wl-small" x="${x}" y="${y+5}">${esc(['CRIANÇA','VÍNCULO 1','VÍNCULO 2'][i])}</text>`).join('')+`<text x="380" y="165" class="wl-text wl-small">RELAÇÕES</text>`;
 }
 return `<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 760 264" role="img" aria-label="Esquema didático sobre ${esc(w.question)}"><title>${esc(w.question)}</title>${inner}</svg>`;
}
function renderWinnicottLab(l){if(activeCourse!==WL_ID||!l.winnLab)return '';
 const w=l.winnLab,st=Math.min(2,Math.max(0,winStage));
 return `<section class="lesson-step win-lab" id="winnicottLab" aria-label="Laboratório interativo Winnicott"><div class="wl-top"><span><b>✦</b> ATELIER / LABORATÓRIO DE EXPERIÊNCIA</span><span>ETAPA ${st+1} DE 3</span></div><h2>${esc(w.question)}</h2><p class="wl-intro">Leia primeiro a teoria. Depois escolha uma etapa do diagrama e experimente uma situação: a explicação muda com sua escolha. Não existe teste de pessoas aqui.</p><div class="wl-stepnav" role="group" aria-label="Etapas do diagrama">${w.steps.map((name,i)=>`<button type="button" data-winstep="${i}" aria-pressed="${i===st}" class="${i===st?'active':''}"><strong>${i+1}</strong>${esc(name)}</button>`).join('')}</div><div class="wl-display"><div class="wl-svgwrap">${wlSVG(l)}</div><div class="wl-feedback" aria-live="polite"><div class="wl-eyebrow">O QUE ESTA ETAPA REVELA</div><h3>${esc(w.steps[st])}</h3><p>${esc(w.insights[st])}</p></div></div><div class="wl-cases"><h3>Agora experimente uma situação</h3><div class="wl-options" role="group" aria-label="Situações para investigar">${w.choices.map((choice,i)=>`<button type="button" data-wincase="${i}" aria-pressed="${winCase===i}" class="${winCase===i?'active':''}">${esc(choice)}</button>`).join('')}</div>${winCase!==-1?`<div class="wl-caseout" aria-live="polite">${esc(w.outcomes[winCase])}<small>Observe o que podemos perguntar — e o que não podemos inferir — a partir desta cena.</small></div>`:'<p style="color:var(--muted);font-size:13px">Selecione uma situação para conhecer a leitura teórica e seus limites.</p>'}</div><button class="wl-comparebtn" type="button" data-wincompare aria-expanded="${winCompare}">${winCompare?'Ocultar comparação −':'Comparar as três etapas +'} </button>${winCompare?`<div class="wl-comparisons">${w.steps.map((t,i)=>`<div><strong>${esc(t)}</strong><p>${esc(w.insights[i])}</p></div>`).join('')}</div>`:''}<p class="wl-boundary"><b>Limite da representação:</b> ${esc(w.limit)}</p></section>`;
}
function wlHandle(b){if(activeCourse!==WL_ID||!activeLesson||!b.closest('#winnicottLab'))return false;
 let changed=false;
 if(b.dataset.winstep!==undefined){winStage=Math.max(0,Math.min(2,Number(b.dataset.winstep)||0));changed=true}
 if(b.dataset.wincase!==undefined){winCase=Math.max(0,Math.min(2,Number(b.dataset.wincase)||0));changed=true}
 if(b.dataset.wincompare!==undefined){winCompare=!winCompare;changed=true}
 if(changed){const el=document.querySelector('#winnicottLab'),ctx=loc(activeLesson);if(el&&ctx)el.outerHTML=renderWinnicottLab(ctx.l);return true}
 return false;
}


function renderLacanBridge(l){
 const b=l.atelierBridge;if(!b)return '';
 return `<section class="lac-intro-guide" aria-label="Introdução acessível à aula"><div class="step-caption">COMECE AQUI · ANTES DOS TERMOS TÉCNICOS</div><h2>Uma situação para pensar</h2><p>${esc(b.scene)}</p><div class="lac-prompt"><strong>Antes de ler a explicação:</strong> o que essa situação faz você perguntar?</div><details><summary>Revelar a ligação com a teoria</summary><div class="lac-reveal"><p>${esc(b.insight)}</p><p><b>Um limite importante:</b> ${esc(b.limit)}</p></div></details><div class="lac-goal"><strong>Ao final desta aula, você deverá conseguir:</strong> ${esc(b.goal)}.</div></section>`;
}
// Preferência local de acessibilidade, independente de cursos e backups.
const ATELIER_FONT_LEVELS=[.85,1,1.15,1.3,1.45,1.6];
let atelierFontIndex=1;
try {const stored=Number(localStorage.getItem('atelier-font-index'));
 if(Number.isInteger(stored)&&stored>=0&&stored<ATELIER_FONT_LEVELS.length)atelierFontIndex=stored;
} catch(e){}
function updateAtelierFont(next){
 atelierFontIndex=Math.max(0,Math.min(ATELIER_FONT_LEVELS.length-1,Number(next)||0));
 try{localStorage.setItem('atelier-font-index',String(atelierFontIndex))}catch(e){}
 const reader=document.querySelector('.reader'); if(!reader)return;
 reader.style.setProperty('--reader-font-scale',String(ATELIER_FONT_LEVELS[atelierFontIndex]));
 const value=reader.querySelector('#readerFontValue');if(value)value.textContent=Math.round(ATELIER_FONT_LEVELS[atelierFontIndex]*100)+'%';
 const less=reader.querySelector('[data-font-step="-1"]'),more=reader.querySelector('[data-font-step="1"]');
 if(less)less.disabled=atelierFontIndex===0;
 if(more)more.disabled=atelierFontIndex===ATELIER_FONT_LEVELS.length-1;
}
function renderLesson(){let ctx=loc(activeLesson);if(!ctx)return renderHome();let {m,l}=ctx,all=allLessons(),idx=all.findIndex(x=>x.id===l.id),qid=doneId(l.id);let qu=l.quiz||{},pre=all[idx-1],next=all[idx+1],choices=qu.options||[],quizSaved=quizData[qid],feedback=quizSaved?.checked?`<div class="quiz-feedback ${quizSaved.selected===Number(qu.correct)?'':'bad'}"><b>${quizSaved.selected===Number(qu.correct)?'Resposta correta.':'Ainda não é essa.'}</b><br>${esc(qu.feedback||'Releia a explicação e tente novamente.')}</div>`:'';
return `<article class="reader" style="--reader-font-scale:${ATELIER_FONT_LEVELS[atelierFontIndex]}"><div class="lesson-meta"><span class="eyebrow">${esc(m.title)}</span><span>·</span><span>AULA ${idx+1} DE ${all.length}</span><span>·</span><span>${Number(l.minutes||12)} MIN</span></div><h1 class="serif">${esc(l.title)}</h1><p class="subtitle">${esc(l.hook||'O que este tema nos convida a pensar?')}</p>${['seminarios-lacanianos','seminarios-kleinianos','seminarios-winnicottianos'].includes(activeCourse)?'<div class="at-lesson-nav"><span>PERGUNTA → TEORIA → EXPERIMENTO → EXERCÍCIO</span><button type="button" data-action="jumpLab">Explorar laboratório ↓</button></div>':''}<div class="lesson-tools"><span style="font-size:12px;color:var(--muted)">${isDone(l.id)?'✓ Aula concluída':'○ Aula em andamento'}</span><div class="reader-font-controls" role="group" aria-label="Ajustar tamanho da fonte da aula"><span class="reader-font-label">Texto</span><button type="button" class="reader-font-btn" data-font-step="-1" aria-label="Diminuir o tamanho da fonte" title="Diminuir fonte" ${atelierFontIndex===0?'disabled':''}>A−</button><output id="readerFontValue" aria-live="polite">${Math.round(ATELIER_FONT_LEVELS[atelierFontIndex]*100)}%</output><button type="button" class="reader-font-btn" data-font-step="1" aria-label="Aumentar o tamanho da fonte" title="Aumentar fonte" ${atelierFontIndex===ATELIER_FONT_LEVELS.length-1?'disabled':''}>A+</button><button type="button" class="reader-font-btn reader-font-reset" data-font-step="reset" aria-label="Restaurar tamanho da fonte">Padrão</button></div><div class="right-tools"><button class="btn sm ghost" data-editlesson="${esc(l.id)}">✎ Editar aula</button><button class="btn sm" data-action="toggleComplete">${isDone(l.id)?'Marcar como não estudada':'Marcar como estudada'}</button></div></div>
${l.id==='freud_a016'&&activeCourse==='formacao-freudiana'?'<div class="dream-entry"><div><span>☾ EXPERIÊNCIA JOGÁVEL</span><strong>A Fábrica dos Sonhos</strong><p>Explore um quarto, misture lembranças, ilumine pistas e monte um sonho impossível.</p></div><button type="button" class="btn primary" data-action="jumpDream">Iniciar aventura ↓</button></div>':''}
<section class="lesson-step question-opening"><div class="step-caption"><span class="step-num">01</span> ANTES DE COMEÇAR</div><h2>${esc(l.hook||'O que você já sabe sobre isso?')}</h2><div class="guide"><b>↗</b><span>Não procure uma resposta perfeita agora. Volte a esta pergunta depois da aula e observe se sua compreensão mudou.</span></div></section>
${activeCourse==='seminarios-lacanianos' && l.atelierBridge?renderLacanBridge(l):''}<section class="lesson-step"><div class="step-caption"><span class="step-num">02</span> PRIMEIRO CONTATO</div><h2>Entenda a ideia central</h2>${prose(l.lead)}</section>
<section class="lesson-step"><div class="step-caption"><span class="step-num">03</span> TEORIA EM DETALHES</div><h2>Construindo o conceito</h2>${((hasFreudMotion(l)||hasNeuroMotion(l))?(l.blocks||[]).slice(0,6):(l.blocks||[])).map(b=>`<div class="theory-block"><h3>${esc(b.title)}</h3>${prose(b.body)}</div>`).join('')}</section>
 ${hasFreudMotion(l)?renderFreudMotion(l.id):''}
 ${l.id==='freud_a003'&&activeCourse==='formacao-freudiana'&&window.AtelierDefesaGame?window.AtelierDefesaGame.render():''}
 ${l.id==='freud_a016'&&activeCourse==='formacao-freudiana'&&window.AtelierDreamForge?window.AtelierDreamForge.render():''}
 ${hasNeuroMotion(l)&&l.id!=='freud_a003'?renderND(l.id):''}
 ${hasNeuroMotion(l)&&(l.blocks||[]).length>6?`<section class="lesson-step"><div class="step-caption">↗ DEPOIS DA EXPERIÊNCIA</div><h2>Agora aprofunde o que você explorou</h2><p>O laboratório serve para comparar hipóteses. Continue a leitura para entender nuances, objeções e limites que nenhuma seta consegue mostrar.</p>${l.blocks.slice(6).map(b=>`<div class="theory-block"><h3>${esc(b.title)}</h3>${prose(b.body)}</div>`).join('')}</section>`:''}
 ${hasFreudMotion(l)&&(l.blocks||[]).length>6?`<section class="lesson-step"><div class="step-caption">↗ VOLTANDO À TEORIA</div><h2>Agora aprofunde o que observou</h2><p>Depois de explorar a animação, continue a leitura. Volte ao laboratório quando quiser: cada pergunta ajuda a interpretar melhor a história.</p>${l.blocks.slice(6).map(b=>`<div class="theory-block"><h3>${esc(b.title)}</h3>${prose(b.body)}</div>`).join('')}</section>`:''}
${renderLacanExperience(l.id)}
${renderLacanExpansion(l)}
${renderKleinExperience(l)}
${renderWinnicottLab(l)}
<section class="lesson-step example"><div class="step-caption"><span class="step-num">04</span> COLOCANDO EM CONTEXTO</div><h2>${esc(l.example?.title||'Um exemplo para pensar')}</h2>${prose(l.example?.body)}</section>
${l.lab?`<section class="lesson-step"><div class="step-caption"><span class="step-num">05</span> LABORATÓRIO GUIADO</div><h2>Explore uma relação</h2><p>Selecione as partes do modelo e acompanhe o que muda na explicação. A visualização é didática, não um desenho anatômico ou um diagnóstico.</p><div id="labBox">${renderLab(l.lab)}</div></section>`:''}
<section class="lesson-step"><div class="step-caption"><span class="step-num">${l.lab?'06':'05'}</span> VOCABULÁRIO</div><h2>Palavras para guardar</h2><p>Toque em cada conceito para revelar seu significado. Tente explicá-lo antes de abrir a resposta.</p><div class="flash-grid">${(l.terms||[]).map((x,i)=>`<button class="flash" data-flash="${i}" aria-expanded="false"><b>${esc(x.term)}</b><span>Toque para revelar ↓</span><span class="definition hidden">${esc(x.desc)}</span></button>`).join('')}</div></section>
${qu.question && choices.length===3 && choices.every(x=>String(x||'').trim())?`<section class="lesson-step"><div class="step-caption"><span class="step-num">${l.lab?'07':'06'}</span> VERIFICAÇÃO DE COMPREENSÃO</div><h2>Você compreendeu?</h2><p style="color:var(--text)">${esc(qu.question)}</p><div id="quizChoices">${choices.map((t,i)=>`<button class="quiz-option ${selectedAnswer===i?'selected':''}" data-answer="${i}" aria-pressed="${selectedAnswer===i}"><span class="option-letter">${'ABC'[i]||i+1}.</span><span>${esc(t)}</span></button>`).join('')}</div><button class="btn primary" data-action="checkAnswer" ${selectedAnswer===null?'disabled style="opacity:.5;cursor:not-allowed"':''}>Verificar resposta</button><div id="feedbackArea">${feedback}</div></section>`:`<section class="lesson-step"><div class="step-caption">EXERCÍCIO</div><h2>Esta aula ainda não tem exercício</h2><p>Quando quiser, edite esta aula e acrescente uma pergunta com três alternativas e a explicação da resposta. Por enquanto, você pode concluir a leitura normalmente.</p><button class="btn" data-editlesson="${esc(l.id)}">＋ Criar exercício</button></section>`}
<section class="lesson-step"><div class="step-caption"><span class="step-num">${l.lab?'08':'07'}</span> SEU CADERNO</div><h2>O que ficou da aula?</h2><p>Escreva com suas palavras a ideia principal, uma dúvida ou uma conexão com outro conceito.</p><textarea class="notes-field" id="noteField" placeholder="Minhas anotações sobre esta aula…">${esc(notes[qid]||'')}</textarea><div class="notes-hint" id="noteStatus">Salvo automaticamente neste navegador.</div></section>
<section class="lesson-step"><div class="step-caption">REFERÊNCIAS · LEITURA COMPLEMENTAR</div><h2>Para aprofundar</h2><ul class="ref-list">${(l.refs||[]).map(x=>`<li>${esc(x).replace(/https?:\/\/[^\s<]+/g,u=>`<a href="${u}" target="_blank" rel="noopener noreferrer" style="color:var(--accent);overflow-wrap:anywhere">${u}</a>`)}</li>`).join('')}</ul><p style="font-size:12px">As referências indicam obras e anos de publicação; a paginação muda conforme a edição. Exemplos didáticos não substituem a formulação dos autores.</p></section>
<div class="complete-strip"><div><strong>${isDone(l.id)?'Aula marcada como concluída.':'Conclua quando sentir que compreendeu.'}</strong><span>Você pode voltar aqui quantas vezes quiser.</span></div><button class="btn ${isDone(l.id)?'':'primary'}" data-action="toggleComplete">${isDone(l.id)?'✓ Concluída':'✓ Concluir esta aula'}</button></div>
<footer class="lesson-footer">${pre?`<button class="btn" data-lesson="${esc(pre.id)}">← Aula anterior</button>`:'<span></span>'}${next?`<button class="btn primary" data-lesson="${esc(next.id)}">Próxima aula →</button>`:`<button class="btn primary" data-view="home">Voltar ao início →</button>`}</footer>
</article>`}
function renderLab(kind){if(kind==='topica'){let arr=[['Cs.','Consciente','Aquilo que está presente à experiência consciente neste momento. Não equivale à totalidade da vida psíquica.'],['Pcs.','Pré-consciente','Um conteúdo não está no foco agora, mas pode ser lembrado sem superar barreiras de recalque.'],['Ics.','Inconsciente','No sentido dinâmico freudiano, envolve processos que encontram obstáculos e podem produzir efeitos indiretos.']];let x=arr[activeLab%3];return `<div class="mini-lab"><div class="lab-tabs">${arr.map((a,i)=>`<button data-labtab="${i}" class="${activeLab===i?'active':''}"><b>${a[0]}</b>${a[1]}</button>`).join('')}</div><div class="lab-description"><h3>${x[1]}</h3><p>${x[2]}</p><div class="lab-alert">Observe: não são três gavetas dentro da cabeça. A primeira tópica diferencia condições de acesso e modos de funcionamento.</div></div></div>`}
if(kind==='instancias'){let a=[['Isso','Exigências pulsionais e satisfação não obedecem necessariamente às regras da vida consciente.'],['Eu','Organiza e medeia exigências internas e a realidade; também produz defesas inconscientes.'],['Supereu','Ideais, proibições e autocrítica podem pressionar o eu, inclusive com culpa intensa.']];return `<div class="mini-lab"><div class="lab-tabs">${a.map((x,i)=>`<button class="${activeLab===i?'active':''}" data-labtab="${i}"><b>${['id','ego','superego'][i]}</b>${x[0]}</button>`).join('')}</div><div class="lab-description"><h3>${a[activeLab%3][0]}</h3><p>${a[activeLab%3][1]}</p><div class="lab-alert">Pergunta-guia: ao pensar “quero descansar, mas me sinto culpado”, como o modelo ajuda a descrever uma tensão — sem transformá-la em três personagens?</div></div></div>`}
if(['dupla','setting','tempo','metodo'].includes(kind)){
  const datasets={
    dupla:[['Fala presente','“Você está decepcionado comigo.” O ponto inicial é uma afirmação feita na relação atual. Antes de interpretá-la, é necessário escutar seu contexto.'],['Exploração','Pode-se perguntar em que momentos essa expectativa aparece e o que ela evoca. Uma hipótese transferencial permanece aberta à fala do analisando.'],['Responsabilidade','A conduta real do analista conta: erros, atrasos e falhas precisam ser reconhecidos. A teoria não é desculpa para desconsiderar o que aconteceu.']],
    setting:[['Enquadre combinado','Horários, sigilo, honorários, modalidade e comunicação são explicitados. A previsibilidade pode favorecer segurança, sem garantir interpretações por si só.'],['Mudança necessária','Um atendimento precisa migrar para o formato remoto. Verifique privacidade, condições técnicas e efeitos na relação sem atribuir uma causa única.'],['Ajuste responsável','Registre o novo combinado, dialogue sobre dificuldades e considere acessibilidade. Flexibilidade não é ausência de limites e regra não é punição.']],
    tempo:[['Tempo de relógio','Uma duração previamente combinada facilita previsibilidade. O valor clínico de uma sessão não se mede só por minutos.'],['Tempo de elaboração','Uma associação pode surgir no início ou no fim, e um silêncio pode ter diferentes sentidos. Nenhum deles autoriza uma interpretação automática.'],['Tempo e contrato','Há tradições de sessão variável, mas precisam de contexto, acordo transparente e cuidado. Um corte arbitrário não ganha valor clínico só por ser chamado de técnica.']],
    metodo:[['Material do paciente','“Nunca sou escolhido”, seguido por uma lembrança de convite recusado. São duas falas relevantes, ainda sem interpretação fechada.'],['Hipótese provisória','O analista pode colocar as duas falas em relação e perguntar o que ocorreu. A proposta serve para abrir associações, não para acusar.'],['Retificação e limite','Se a pessoa discordar ou surgir informação nova, a hipótese muda. A escuta e a responsabilidade valem mais do que defender uma explicação bonita.']]
  };
  const a=datasets[kind]; const idx=activeLab%3;return `<div class="mini-lab"><div class="mini-flow">${a.map((x,i)=>`<button class="${idx===i?'active':''}" data-labtab="${i}">${i+1}. ${x[0]}</button>`).join('')}</div><div class="lab-description"><h3>${a[idx][0]}</h3><p>${a[idx][1]}</p><div class="lab-alert">O laboratório compara situações possíveis. Não interpreta uma pessoa real nem fornece diagnóstico.</div></div></div>`;
}
let a=[['Situação','A pessoa diz: “Fico receosa de discordar de você, mesmo quando penso diferente”. O dado inicial é a fala presente na relação.'],['Investigação','O analista pode escutar o que essa expectativa evoca na história da pessoa. É uma hipótese aberta, não uma revelação automática.'],['Limite','Discordar também pode ser uma resposta legítima a algo dito pelo analista. A relação real e a responsabilidade profissional continuam importantes.']];return `<div class="mini-lab"><div class="mini-flow">${a.map((x,i)=>`<button class="${activeLab===i?'active':''}" data-labtab="${i}">${i+1}. ${x[0]}</button>`).join('')}</div><div class="lab-description"><h3>${a[activeLab%3][0]}</h3><p>${a[activeLab%3][1]}</p><div class="lab-alert">A transferência não é uma fórmula para atribuir sentimentos ocultos; é uma hipótese clínica situada numa relação.</div></div></div>`}
function renderGlossary(filter=''){let all=allLessons(),map=new Map();all.forEach(l=>(l.terms||[]).forEach(t=>{let key=(t.term||'').trim().toLowerCase();if(!map.has(key))map.set(key,{...t,lesson:l.id})}));let items=[...map.values()].filter(t=>(t.term+' '+t.desc).toLowerCase().includes(filter.toLowerCase())).sort((a,b)=>a.term.localeCompare(b.term,'pt-BR'));return `<section class="utility"><div class="eyebrow">FERRAMENTA DE ESTUDO</div><h1 class="serif">Glossário</h1><p>Consulte os conceitos enquanto estuda. Cada termo leva de volta à aula onde é introduzido.</p><input class="utility-search" id="glossarySearch" type="search" placeholder="Pesquisar um conceito…" value="${esc(filter)}" aria-label="Pesquisar glossário"><div class="dictionary" id="glossaryResults">${items.map(t=>`<div class="dict-card"><h3>${esc(t.term)}</h3><p>${esc(t.desc)}</p><button data-lesson="${esc(t.lesson)}">Ver aula relacionada →</button></div>`).join('')||'<div class="empty">Nenhum conceito encontrado.</div>'}</div></section>`}
const timePoints=[['1856','Nascimento de Sigmund Freud','Ponto de partida biográfico para compreender a formação médica e cultural de Freud.', 'a04'],['1895','Estudos sobre a histeria','Breuer e Freud publicam um trabalho central na história do método catártico.', 'a05'],['1900','A interpretação dos sonhos','Freud organiza a investigação sobre sonhos, desejo e aparelho psíquico.', 'a07'],['1905','Três ensaios sobre a teoria da sexualidade','Formulações que expandem historicamente o sentido de sexualidade.', 'a14'],['1914–1915','Narcisismo e metapsicologia','Conceitos de pulsão, recalque e inconsciente recebem novas articulações.', 'a11'],['1920','Além do princípio do prazer','A repetição ganha destaque em formulações controversas.', 'a25'],['1923','O eu e o isso','O modelo estrutural apresenta isso, eu e supereu.', 'a17'],['1936','Anna Freud e os mecanismos de defesa','Sistematização de processos defensivos.', 'a18'],['1953','Lacan e a fala e a linguagem','Novo percurso teórico do retorno a Freud.', 'a29'],['1971','Winnicott: O brincar e a realidade','Um marco para estudar criatividade, ambiente e experiência transicional.', 'a28']];
const clinicPoints=[['1895','Estudos sobre a histeria','Breuer e Freud registram experiências que precederam a consolidação da técnica.', 'clin_a14'],['1896','Primeira clínica psicológica','Lightner Witmer abre a clínica na Universidade da Pensilvânia; não confundir com a origem da psicanálise.', 'clin_a05'],['1904','O método psicanalítico de Freud','Um retrato histórico da transição metodológica.', 'clin_a12'],['1912','Recomendações para a escuta','Freud discute a postura do analista e a atenção flutuante.', 'clin_a02'],['1913','Sobre o início do tratamento','Condições práticas de início de uma análise.', 'clin_a07'],['1914','Recordar, repetir e elaborar','O manejo da repetição e das resistências passa ao primeiro plano.', 'clin_a15'],['1937','Análise terminável e interminável','Discussão sobre limites e impasses no percurso.', 'clin_a09'],['1958','A direção do tratamento','Lacan discute a posição e os atos do analista.', 'clin_a15']];
function renderTimeline(){if(activeCourse==='clinica-psicanalitica')return `<section class="utility"><div class="eyebrow">HISTÓRIA DO MÉTODO</div><h1 class="serif">Linha do tempo clínica</h1><p>Marcos selecionados para conectar a evolução da técnica às aulas. Anos indicam publicação ou acontecimento histórico.</p><div class="timeline">${clinicPoints.map(a=>`<div class="timeline-item"><b>${a[0]}</b><h3>${esc(a[1])}</h3><p>${esc(a[2])}</p><button data-lesson="${a[3]}">Estudar tema →</button></div>`).join('')}</div></section>`;if(activeCourse!=='intro')return `<section class="utility"><div class="eyebrow">FERRAMENTA DE ESTUDO</div><h1 class="serif">Linha do tempo</h1><p>A linha do tempo histórica está disponível no curso de Introdução à Psicanálise. Seus cursos adicionais podem ter uma cronologia própria no conteúdo das aulas.</p><button class="btn" data-view="home">Voltar ao curso</button></section>`;return `<section class="utility"><div class="eyebrow">HISTÓRIA DAS IDEIAS</div><h1 class="serif">Linha do tempo</h1><p>Datas selecionadas de obras e acontecimentos. Clique para conectar cada momento a uma aula. A lista é introdutória, não exaustiva.</p><div class="timeline">${timePoints.map(a=>`<div class="timeline-item"><b>${a[0]}</b><h3>${esc(a[1])}</h3><p>${esc(a[2])}</p><button data-lesson="${a[3]}">Estudar tema →</button></div>`).join('')}</div></section>`}
// Dialog and editing
function modal(title,body,footer=''){document.getElementById('modalRoot').innerHTML=`<div class="modal-back" id="modalBack"><section class="modal" role="dialog" aria-modal="true" aria-labelledby="modalTitle"><header class="modal-header"><h2 id="modalTitle">${esc(title)}</h2><button class="icon-btn" data-action="closeModal" aria-label="Fechar">✕</button></header><div class="modal-body">${body}</div><footer class="modal-footer">${footer||'<span></span><button class="btn" data-action="closeModal">Fechar</button>'}</footer></section></div>`;let node=$('#modalBack .field input,#modalBack button');if(node)node.focus()}
function closeModal(){document.getElementById('modalRoot').innerHTML=''}
function field(label,name,value='',type='text',hint=''){return `<div class="field"><label for="f_${name}">${esc(label)}</label>${type==='textarea'?`<textarea id="f_${name}" name="${name}">${esc(value)}</textarea>`:`<input type="${type}" id="f_${name}" name="${name}" value="${esc(value)}">`}${hint?`<small>${esc(hint)}</small>`:''}</div>`}
function foot(saveText='Salvar',del=false){const tools=del?`<button class="btn danger" type="button" data-action="deleteEntity">Excluir</button>${editState?.type==='course'?'':'<button class="btn" type="button" data-action="moveUp" title="Mover para cima">↑</button><button class="btn" type="button" data-action="moveDown" title="Mover para baixo">↓</button>'}`:'';return `<div style="display:flex;gap:6px;flex-wrap:wrap">${tools}</div><div style="display:flex;gap:9px"><button class="btn" type="button" data-action="closeModal">Cancelar</button><button type="submit" form="editorForm" class="btn primary">${esc(saveText)}</button></div>`}

let editState=null;
function editCourse(id=null){let c=id?courses.find(x=>x.id===id):null;editState={type:'course',id};modal(c?'Editar curso':'Novo curso',`<form id="editorForm">${field('Nome do curso *','title',c?.title||'')}${field('Descrição curta','subtitle',c?.subtitle||'')}${field('Símbolo ou emoji','icon',c?.icon||'✦')}<div class="helper-box">O curso aparecerá no seletor lateral. Depois você poderá adicionar módulos e aulas sem editar o arquivo HTML.</div></form>`,foot(c?'Salvar alterações':'Criar curso',!!c));}
function editModule(id=null){let m=id?course().modules.find(x=>x.id===id):null;editState={type:'module',id};modal(m?'Editar módulo':'Novo módulo',`<form id="editorForm">${field('Título do módulo *','title',m?.title||'')}${field('Apresentação','description',m?.description||'','textarea')}<div class="helper-box">Os módulos organizam a sequência de aprendizagem. Você poderá acrescentar aulas depois.</div></form>`,foot(m?'Salvar módulo':'Criar módulo',!!m));}
function termString(l){return (l?.terms||[]).map(x=>x.term+' | '+x.desc).join('\n')}
function editLesson(id=null){let ctx=id?loc(id):null,l=ctx?.l||{},m=ctx?.m;editState={type:'lesson',id,originalModule:m?.id,originalIndex:m?m.lessons.findIndex(x=>x.id===id):-1};let blocks=l.blocks||[];const section=(i)=>`<div class="form-grid">${field('Título da seção '+(i+1),`btitle${i}`,blocks[i]?.title||'')}${field('Explicação (use linhas em branco para separar parágrafos)',`bbody${i}`,blocks[i]?.body||'','textarea')}</div>`;
const moduleChooser=`<div class="field"><label for="f_module">Módulo</label><select id="f_module" name="module">${course().modules.map(x=>`<option value="${esc(x.id)}" ${x.id===m?.id?'selected':''}>${esc(x.title)}</option>`).join('')}</select></div>`;
modal(id?'Editar aula':'Adicionar aula',`<form id="editorForm">${moduleChooser}${field('Título da aula *','title',l.title||'')}<div class="form-grid">${field('Tempo estimado (minutos)','minutes',l.minutes||12,'number')}${field('Pergunta inicial','hook',l.hook||'')}</div>${field('Explicação introdutória','lead',l.lead||'','textarea')}<div class="editor-heading">Teoria em etapas</div>${[0,1,2].map(section).join('')}<div class="editor-heading">Exemplo e conceitos</div>${field('Exemplo para pensar','example',l.example?.body||'','textarea')}${field('Conceitos-chave','terms',termString(l),'textarea','Uma linha por conceito no formato: Nome | Definição')}<div class="editor-heading">Verificação de compreensão</div>${field('Pergunta do exercício','question',l.quiz?.question||'')}${field('Alternativa A','op0',l.quiz?.options?.[0]||'')}${field('Alternativa B','op1',l.quiz?.options?.[1]||'')}${field('Alternativa C','op2',l.quiz?.options?.[2]||'')}<div class="field"><label for="f_correct">Alternativa correta</label><select id="f_correct" name="correct">${['A','B','C'].map((x,i)=>`<option value="${i}" ${Number(l.quiz?.correct||0)===i?'selected':''}>${x}</option>`).join('')}</select></div>${field('Explicação da resposta','feedback',l.quiz?.feedback||'','textarea')}<div class="editor-heading">Fontes</div>${field('Referências bibliográficas','refs',(l.refs||[]).join('\n'),'textarea','Uma obra por linha. Confirme os dados bibliográficos antes de publicar.')}</form>`,foot(id?'Salvar alterações':'Criar aula',!!id))}
function uniqueId(prefix){return prefix+Date.now().toString(36)+Math.random().toString(36).slice(2,6)}
function saveEditor(form){let data=Object.fromEntries(new FormData(form));if(!String(data.title||'').trim()){toast('Preencha o título antes de salvar.');return}let s=editState,c=course();
if(s.type==='course'){let item=s.id?courses.find(x=>x.id===s.id):null;if(!item){item={id:uniqueId('c'),title:'',subtitle:'',icon:'✦',modules:[]};courses.push(item)}item.title=data.title.trim();item.subtitle=data.subtitle;item.icon=data.icon||'✦';activeCourse=item.id;activeLesson=null;view='home'}
if(s.type==='module'){let item=s.id?c.modules.find(x=>x.id===s.id):null;if(!item){item={id:uniqueId('m'),title:'',description:'',lessons:[]};c.modules.push(item)}item.title=data.title.trim();item.description=data.description}
if(s.type==='lesson'){let target=c.modules.find(x=>x.id===data.module);if(!target){toast('Crie primeiro um módulo.');return}let item=s.id?loc(s.id)?.l:null;if(item){c.modules.forEach(m=>m.lessons=m.lessons.filter(l=>l.id!==item.id))}else item={id:uniqueId('l')};item.title=data.title.trim();item.minutes=Math.max(1,Number(data.minutes)||12);item.hook=data.hook;item.lead=data.lead;const existingExtraBlocks=s.id?(item.blocks||[]).slice(3):[];item.blocks=[0,1,2].map(i=>({title:data['btitle'+i]||'Explorando a teoria',body:data['bbody'+i]||''})).filter(x=>x.body.trim());if(existingExtraBlocks.length)item.blocks.push(...existingExtraBlocks);item.example={title:'Um exemplo para pensar',body:data.example};item.terms=String(data.terms||'').split(/\r?\n/).filter(Boolean).map(x=>{let [term,...rest]=x.split('|');return {term:term.trim(),desc:rest.join('|').trim()||'Conceito a aprofundar.'}});item.quiz={question:data.question,options:[data.op0,data.op1,data.op2],correct:Number(data.correct)||0,feedback:data.feedback};item.refs=String(data.refs||'').split(/\r?\n/).map(x=>x.trim()).filter(Boolean);if(s.id&&s.originalModule===target.id){target.lessons.splice(Math.max(0,s.originalIndex),0,item)}else{target.lessons.push(item)}activeLesson=item.id;view='lesson';expanded[target.id]=true}
save();closeModal();render();toast('Conteúdo salvo no navegador.')}
function moveEntity(direction){const s=editState;if(!s?.id||s.type==='course')return;let arr;if(s.type==='module')arr=course().modules;else{let current=loc(s.id);arr=current?.m.lessons;}if(!arr)return;let idx=arr.findIndex(x=>x.id===s.id),next=idx+direction;if(idx<0||next<0||next>=arr.length){toast('Este item já está no limite da lista.');return;}[arr[idx],arr[next]]=[arr[next],arr[idx]];if(s.type==='lesson')s.originalIndex=next;save();renderSidebar();toast('Ordem alterada. Salve o formulário antes de sair se também editou textos.');}
function deleteEntity(){const s=editState;if(!s)return;let name=s.type==='course'?'este curso e todos seus módulos e aulas':s.type==='module'?'este módulo e todas as aulas':'esta aula';if(!confirm('Excluir '+name+'? Esta ação não pode ser desfeita sem um backup.'))return;
if(s.type==='course'){if(courses.length===1){toast('Mantenha ao menos um curso.');return}courses=courses.filter(x=>x.id!==s.id);activeCourse=courses[0].id;view='home';activeLesson=null}
if(s.type==='module'){course().modules=course().modules.filter(x=>x.id!==s.id);view='home';activeLesson=null}
if(s.type==='lesson'){course().modules.forEach(m=>m.lessons=m.lessons.filter(l=>l.id!==s.id));view='home';activeLesson=null}
save();closeModal();render();toast('Conteúdo excluído.')}
function manageDialog(){modal('Construir seu curso',`<p style="color:var(--muted);line-height:1.8;margin-top:0">Adicione conteúdos sem código. Cursos contêm módulos, e cada módulo contém aulas com teoria, exemplos, conceitos e exercícios.</p><div class="manage-grid"><button data-action="newCourse"><b>＋ Novo curso</b><span>Crie um curso separado no seletor.</span></button><button data-action="newModule"><b>＋ Novo módulo</b><span>Organize uma nova sequência de aulas.</span></button><button data-action="newLesson"><b>＋ Nova aula</b><span>Escreva uma aula completa com exercícios.</span></button><button data-action="backup"><b>⇩ Fazer backup</b><span>Exporte seus cursos e progresso em JSON.</span></button></div><div class="helper-box"><b style="color:var(--text)">Importante:</b> mudanças são salvas neste navegador, neste dispositivo. Se você limpar os dados do navegador ou abrir o arquivo em outro aparelho, elas não acompanharão automaticamente. Exporte um backup após editar.</div>`)}
function backupDialog(){modal('Seus dados e backups',`<div class="helper-box"><b style="color:var(--text)">O que entra no arquivo?</b><br>Todos os cursos e aulas (inclusive suas edições), anotações, respostas dos exercícios e progresso. A exportação não envia nada para a internet.</div><div class="manage-grid"><button data-action="export"><b>↓ Exportar backup (.json)</b><span>Guarde uma cópia antes de mudar de navegador.</span></button><button data-action="import"><b>↑ Importar backup (.json)</b><span>Restaura os dados de um arquivo exportado pelo aplicativo.</span></button></div><p style="font-size:12px;line-height:1.7;color:var(--quiet)">Importar substituirá seus cursos atuais e as anotações/progresso pelos dados do backup, preservando também os cursos novos que venham incluídos nesta versão. Faça uma cópia antes. O aplicativo pedirá confirmação.</p><input type="file" class="file-hidden" id="importFile" accept=".json,application/json">`)}
function exportBackup(){let obj={format:'caderno-psica',version:2,exportedAt:new Date().toISOString(),courses,progress,notes,quiz:quizData};let blob=new Blob([JSON.stringify(obj,null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='backup-atelier-psicanalise-'+new Date().toISOString().slice(0,10)+'.json';document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('Backup exportado. Guarde o arquivo em local seguro.')}
async function importBackup(input){let f=input.files?.[0];if(!f)return;try{let d=JSON.parse(await f.text());if(d.format!=='caderno-psica'||!Array.isArray(d.courses)||!d.courses.length||!d.courses.every(x=>typeof x.id==='string'&&Array.isArray(x.modules)&&x.modules.every(m=>typeof m.title==='string'&&Array.isArray(m.lessons)&&m.lessons.every(l=>typeof l.id==='string'&&typeof l.title==='string'))))throw Error('Arquivo incompatível.');if(!confirm('Importar vai substituir suas alterações e seu progresso pelos dados do arquivo. Os cursos incluídos nesta versão serão mantidos caso não estejam no backup. Continuar?'))return;courses=d.courses;window.START_COURSES.forEach(c=>{if(!courses.some(x=>x.id===c.id))courses.push(clone(c))});mergeNewLacanModules();applyLacanReaderUpdates();progress=d.progress||{};notes=d.notes||{};quizData=d.quiz||{};activeCourse=courses[0].id;view='home';activeLesson=null;save();closeModal();render();toast('Backup importado com sucesso.')}catch(e){toast('Não foi possível importar: '+e.message)}}
function toast(msg){let host=$('#toastHost');host.innerHTML=`<div class="toast">${esc(msg)}</div>`;clearTimeout(window.__toastT);window.__toastT=setTimeout(()=>host.innerHTML='',4000)}
function closeMobile(){$('#sidebar').classList.remove('mobile-visible');$('#shade').classList.remove('visible')}
function openMobile(){$('#sidebar').classList.add('mobile-visible');$('#shade').classList.add('visible')}
// All app interactions, including new editor buttons, are delegated.
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;
if(b.dataset.fontStep!==undefined){updateAtelierFont(b.dataset.fontStep==='reset'?1:atelierFontIndex+Number(b.dataset.fontStep));return;}
if(b.dataset.kleinstage!==undefined){
 kleinStage=Math.min(2,Math.max(0,Number(b.dataset.kleinstage)||0));
 const lab=document.querySelector('#kleinLab'),item=loc(activeLesson)?.l;
 if(lab&&item){lab.outerHTML=renderKleinExperience(item);document.querySelector('[data-kleinstage="'+kleinStage+'"]').focus({preventScroll:true})}
 return;
}
if(b.dataset.kleincompare!==undefined){
 kleinCompare=!kleinCompare;const lab=document.querySelector('#kleinLab'),item=loc(activeLesson)?.l;
 if(lab&&item){lab.outerHTML=renderKleinExperience(item);document.querySelector('[data-kleincompare]').focus({preventScroll:true})}
 return;
}
if(b.closest('#winnicottLab')&&wlHandle(b))return;
if(b.closest('#lacExpansionLab')&&lxHandle(b))return;
if(b.id==='courseBtn'){let el=$('#coursePicker'),open=el.classList.toggle('hidden');el.innerHTML=courses.map(c=>`<button data-course="${esc(c.id)}">${esc(c.icon||'✦')} &nbsp; ${esc(c.title)}</button>`).join('')+'<button class="add-course" data-action="newCourse">＋ Criar outro curso</button>';b.setAttribute('aria-expanded',String(!open));return}
if(b.dataset.course){activeCourse=b.dataset.course;view='home';activeLesson=null;$('#sidebarSearch').value='';save();render();closeMobile();return}
if(b.dataset.toggle){expanded[b.dataset.toggle]=expanded[b.dataset.toggle]===false?true:false;renderSidebar();return}
if(b.dataset.lesson){if(b.dataset.lesson)goLesson(b.dataset.lesson);return}
if(b.dataset.view){if(b.dataset.view==='home')goHome();else goView(b.dataset.view);return}
if(b.dataset.editmodule){editModule(b.dataset.editmodule);return}
if(b.dataset.editlesson){editLesson(b.dataset.editlesson);return}
if(b.dataset.flash!==undefined){let el=b.querySelector('.definition'),span=b.querySelector('span:not(.definition)');el.classList.toggle('hidden');b.setAttribute('aria-expanded',String(!el.classList.contains('hidden')));if(span)span.textContent=el.classList.contains('hidden')?'Toque para revelar ↓':'Toque para ocultar ↑';return}
if(b.dataset.answer!==undefined){selectedAnswer=Number(b.dataset.answer);$('#quizChoices').querySelectorAll('.quiz-option').forEach(x=>{x.classList.toggle('selected',Number(x.dataset.answer)===selectedAnswer);x.setAttribute('aria-pressed',String(Number(x.dataset.answer)===selectedAnswer))});const ch=$('[data-action="checkAnswer"]');ch.disabled=false;ch.style.opacity='1';ch.style.cursor='pointer';return}
if(b.closest("#atelierLab, #lacanLab") && atHandle(b))return; if(b.closest("#languageLab") && llHandle(b))return; if(b.dataset.lcstep!==undefined){lcUpdate(Number(b.dataset.lcstep));return}if(b.dataset.lcprev!==undefined){lcUpdate(lcActiveStep-1);return}if(b.dataset.lcnext!==undefined){lcUpdate(lcActiveStep+1);return} if(b.dataset.labtab!==undefined){activeLab=Number(b.dataset.labtab);$('#labBox').innerHTML=renderLab(loc(activeLesson).l.lab);return}
 if(b.dataset.nd!==undefined){ndSelect(b.dataset.nd,Number(b.dataset.ndindex));return}
 if(b.dataset.fmlens!==undefined){fmSelectLens(Number(b.dataset.fmlens));return}
 if(b.dataset.fmanswer!==undefined){fmChooseAnswer(Number(b.dataset.fmanswer));return}
 if(b.dataset.fmtime!==undefined){fmStop();fmUpdateTime(Number(b.dataset.fmtime));fmSyncPlay();return}
 if(b.dataset.fmcontrol!==undefined){fmControl(b.dataset.fmcontrol);return}
const action=b.dataset.action; if(action==='openDreamGame'){openDreamGame();return} if(action==='jumpDream'){const target=document.getElementById('dreamForge');if(target)target.scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'auto':'smooth',block:'start'});return} if(action==='openDefesaGame'){openDefesaGame();return} if(action==='jumpLab'){let lab=document.querySelector('#winnicottLab,#lacExpansionLab,#kleinLab,#atelierLab,#languageLab,#lacanLab');if(lab)lab.scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'auto':'smooth',block:'start'});return}
if(action==='toggleComplete'){progress[doneId(activeLesson)]=!isDone(activeLesson);save();render();return}
if(action==='checkAnswer'){if(selectedAnswer===null)return;const item=loc(activeLesson).l;quizData[doneId(activeLesson)]={selected:selectedAnswer,checked:true};if(selectedAnswer===Number(item.quiz?.correct))progress[doneId(activeLesson)]=true;save();refreshNav();if(isDone(activeLesson)){const foot=$('.complete-strip .btn');if(foot){foot.textContent='✓ Concluída';foot.classList.remove('primary')}const lab=$('.lesson-tools > span');if(lab)lab.textContent='✓ Aula concluída';}$('#feedbackArea').innerHTML=`<div class="quiz-feedback ${selectedAnswer===Number(item.quiz?.correct)?'':'bad'}"><b>${selectedAnswer===Number(item.quiz?.correct)?'Resposta correta. Aula marcada como concluída.':'Ainda não é essa. Você pode tentar novamente.'}</b><br>${esc(item.quiz?.feedback||'')}</div>`;return}
if(action==='closeModal'){closeModal();return}if(action==='newCourse'){editCourse();return}if(action==='newModule'){editModule();return}if(action==='newLesson'){if(!course().modules.length){toast('Crie primeiro um módulo.');editModule();return}editLesson();return}if(action==='manage'){manageDialog();return}if(action==='backup'){backupDialog();return}if(action==='export'){exportBackup();return}if(action==='import'){$('#importFile')?.click();return}if(action==='deleteEntity'){deleteEntity();return}if(action==='moveUp'){moveEntity(-1);return}if(action==='moveDown'){moveEntity(1);return}
if(b.id==='mobileOpen'){openMobile();return}if(b.id==='manageBtn'){closeMobile();manageDialog();return}if(b.id==='backupBtn'){closeMobile();backupDialog();return}if(b.id==='topManage'){if(!course().modules.length)editModule();else editLesson();return}if(b.id==='courseEditBtn'){editCourse(activeCourse);return}if(b.id==='addModuleBtn'){editModule();return}
});
document.addEventListener('submit',e=>{if(e.target.id==='editorForm'){e.preventDefault();saveEditor(e.target)}});
document.addEventListener('input',e=>{if(e.target.id==='sidebarSearch'){renderSidebar()}if(e.target.id==='noteField'&&activeLesson){notes[doneId(activeLesson)]=e.target.value;save();$('#noteStatus').textContent='✓ Anotação salva neste navegador.'}if(e.target.id==='glossarySearch'){let c=allLessons(),map=new Map();c.forEach(l=>(l.terms||[]).forEach(t=>{let key=t.term.toLowerCase();if(!map.has(key))map.set(key,{...t,lesson:l.id})}));let q=e.target.value.toLocaleLowerCase('pt-BR');$('#glossaryResults').innerHTML=[...map.values()].filter(t=>(t.term+' '+t.desc).toLocaleLowerCase('pt-BR').includes(q)).sort((a,b)=>a.term.localeCompare(b.term,'pt-BR')).map(t=>`<div class="dict-card"><h3>${esc(t.term)}</h3><p>${esc(t.desc)}</p><button data-lesson="${esc(t.lesson)}">Ver aula relacionada →</button></div>`).join('')||'<div class="empty">Nenhum conceito encontrado.</div>'}});
document.addEventListener('change',e=>{if(e.target.id==='importFile')importBackup(e.target)});
$('#shade').addEventListener('click',closeMobile);document.addEventListener('keydown',e=>{if(e.key==='Escape'){closeMobile();closeModal();$('#coursePicker').classList.add('hidden')}});
